mapper.select:
SELECT RO.RES_OPEN_ID , R.CAFE_ID, C.CAFE_NAME , RO.ROOM_ID, R.ROOM_NAME , DATE_FORMAT(RO.OPEN_AT, '%Y-%m-%d %H:%i') AS OPEN_AT , DATE_FORMAT(RO.OPEN_AT, '%Y-%m-%d') AS OPEN_DATE , DATE_FORMAT(RO.OPEN_AT, '%H:%i') AS OPEN_TIME FROM RES_OPEN RO JOIN ROOM R ON RO.ROOM_ID = R.ROOM_ID JOIN CAFE C ON R.CAFE_ID = C.CAFE_ID
R.CAFE_ID IN( SELECT DISTINCT CAFE_ID FROM VW_CAFE_ROOM_INFO WHERE CAFE_OWNER = #{userId} OR CAFE_MANAGER= #{userId} ) AND RO.RES_OPEN_ID NOT IN (SELECT RES_OPEN_ID FROM RES_DROP) AND DATE_FORMAT(RO.OPEN_AT, '%Y-%m-%d') = #{schDate}
AND R.CAFE_ID = #{schCafe}
